from common import *
from verify import JS
src('igeeks-v3'); dom('javascript')
topic('Types & Operators')
M('b','k',"Which keyword declares a block-scoped variable whose value can be reassigned?","let","const","var","static","let is block-scoped and reassignable. const is block-scoped but cannot be reassigned.")
M('b','k',"Which keyword declares a variable that cannot be reassigned?","const","let","final","fixed","A const binding cannot be reassigned, although an object it holds can still be modified.")
JS('b','o',"What does this code print?","console.log(2 + '3')","23","5","'5'","NaN","The + operator concatenates when one operand is a string, so the number 2 becomes '2' and the result is '23'.")
JS('b','o',"What does this code print?","console.log('5' - 2)","3","'52'","52","NaN","The - operator only works on numbers, so the string '5' is converted to 5 and the result is 3.")
JS('b','o',"What does this code print?","console.log(typeof 42)","number","integer","int","string","JavaScript has a single number type, so typeof 42 is 'number'.")
M('b','k',"Which operator compares both value and type?","===","==","=","!=","=== is strict equality and does no type conversion. == converts types first.")
JS('b','o',"What does this code print?","console.log(10 % 3)","1","3","0","3.33","% is the remainder operator: 10 divided by 3 leaves 1.")
JS('b','o',"What does this code print?","console.log(Boolean(''))","false","true","undefined","null","An empty string is falsy, so Boolean('') is false.")
JS('b','o',"What does this code print?","console.log(0.1 + 0.2 === 0.3)","false","true","undefined","NaN","Binary floating point cannot store 0.1 and 0.2 exactly, so the sum is 0.30000000000000004, not 0.3.")
topic('Arrays & Objects')
M('b','k',"Which array method adds an element to the end?","push","append","add","insert","push adds one or more elements at the end and returns the new length.")
M('b','k',"Which method turns a JSON string into a JavaScript value?","JSON.parse","JSON.stringify","JSON.decode","JSON.toObject","JSON.parse reads text into a value. JSON.stringify does the opposite.")
M('b','k',"Which array method joins all elements into one string?","join","concat","merge","toText","[1,2,3].join('-') gives '1-2-3'.")
JS('b','o',"What does this code print?","console.log(Math.max(3, 7, 5))","7","15","3","5","Math.max returns the largest argument, 7.")
JS('b','o',"What does this code print?","console.log('abc'.toUpperCase())","ABC","[ 'A', 'B', 'C' ]","Error","undefined","toUpperCase returns a new string with every letter in capitals.")
topic('DOM & Events')
M('b','k',"Which event fires when a user clicks an element?","click","press","tap","select","Listeners are attached with addEventListener('click', handler).")
topic('Types & Operators')
JS('i','o',"What does this code print?","console.log(typeof null)","object","null","undefined","number","typeof null is 'object', a long-standing quirk of the language.")
JS('i','o',"What does this code print?","console.log(null == undefined, null === undefined)","true false","true true","false false","false true","With loose equality null and undefined are equal to each other. Strict equality also compares type, which differs.")
JS('i','o',"What does this code print?","console.log(1 < 2 < 3, 3 > 2 > 1)","true false","true true","false false","false true","1 < 2 is true, and true < 3 becomes 1 < 3, which is true. 3 > 2 is true, and true > 1 becomes 1 > 1, which is false.")
topic('Functions & Closures')
JS('i','o',"What does this code print?","function counter() { let n = 0; return () => ++n; }\nconst c = counter();\nc(); c();\nconsole.log(c());","3","1","0","undefined","The returned function closes over n. It is incremented on each call, so the third call returns 3.")
JS('i','o',"What does this code print?","console.log(a);\nvar a = 5;","undefined","5","ReferenceError","null","A var declaration is hoisted and initialised with undefined. Only the assignment stays in place.")
topic('Arrays & Objects')
JS('i','o',"What does this code print?","console.log([1, 2] + [3])","1,23","1,2,3","[1,2,3]","6","Arrays are converted to strings before +, so '1,2' + '3' gives '1,23'.")
JS('i','o',"What does this code print?","console.log([10, 9, 1].sort())","[ 1, 10, 9 ]","[ 1, 9, 10 ]","[ 10, 9, 1 ]","[ 9, 10, 1 ]","sort() compares elements as strings by default, so '1' < '10' < '9'. Pass a compare function for numeric order.")
topic('Async & Promises')
JS('a','o',"What order are the values logged in?","const log = [];\nlog.push(1);\nsetTimeout(() => log.push(2), 0);\nPromise.resolve().then(() => log.push(3));\nlog.push(4);\nsetTimeout(() => console.log(log.join(' ')), 10);","1 4 3 2","1 2 3 4","1 3 4 2","1 4 2 3","Synchronous code runs first (1, 4). Then the promise microtask (3) runs before the timer callback (2).")
JS('a','o',"What does this code print?","console.log(typeof (async () => 1)())","object","number","promise","function","An async function always returns a Promise, and typeof a Promise is 'object'.")
M('a','k',"What happens to Promise.all([p1, p2, p3]) if p2 rejects?","It rejects immediately with p2's reason","It waits for all promises and resolves with an array","It resolves with only the successful values","It ignores the rejection","Promise.all fails fast. Use Promise.allSettled to get the outcome of every promise.")
topic('Functions & Closures')
JS('a','o',"What does this code print?","const out = [];\nfor (var i = 0; i < 3; i++) setTimeout(() => out.push(i), 0);\nsetTimeout(() => console.log(out.join(' ')), 10);","3 3 3","0 1 2","0 0 0","undefined","var is function-scoped, so all callbacks share one i, which is 3 when they run. Using let would give 0 1 2.")
JS('a','o',"What does this code print?","const o = { n: 'obj', f() { return [1].map(() => this.n)[0]; } };\nconsole.log(o.f());","obj","undefined","TypeError","null","An arrow function has no this of its own and uses the this of the enclosing f(), which is called on o. A regular callback function would lose that this.")
topic('Arrays & Objects')
JS('a','o',"What does this code print?","const a = { x: { y: 1 } };\nconst b = { ...a };\nb.x.y = 2;\nconsole.log(a.x.y);","2","1","undefined","Error","Spread makes a shallow copy. a.x and b.x are the same object, so the change shows through.")
JS('a','o',"What does this code print?","function* g() { yield 1; yield 2; }\nconsole.log([...g()].join());","1,2","1","2","[object Generator]","Spreading a generator runs it to completion and collects the yielded values.")
JS('a','o',"What does this code print?","console.log(Symbol('a') === Symbol('a'))","false","true","undefined","TypeError","Every Symbol() call creates a unique value, even with the same description.")
JS('a','o',"What does this code print?","console.log(0 ?? 'x', 0 || 'x')","0 x","x x","0 0","x 0","?? only replaces null or undefined, so 0 is kept. || replaces every falsy value, so 0 becomes 'x'.")
JS('a','o',"What does this code print?","const a = { b: null };\nconsole.log(a?.b?.c ?? 'none')","none","undefined","null","TypeError","Optional chaining stops at null and gives undefined. ?? then supplies the fallback 'none'.")
JS('a','o',"What does this code print?","console.log(typeof Object.create(null).toString)","undefined","function","object","string","Object.create(null) makes an object with no prototype, so it does not inherit toString.")
topic('Modules & Modern JS')
M('a','k',"Why can a WeakMap not use a string as a key?","Its keys must be objects, which can be garbage collected when nothing else refers to them","Strings are too long","WeakMap only stores numbers","Strings are not hashable in JavaScript","WeakMap holds its keys weakly. Primitive values have no identity that could be collected, so they are not allowed.")
M('a','k',"What does a Proxy get trap let you do?","Intercept reads of properties on the target object","Stop the object being garbage collected","Copy the object deeply","Freeze the object","The handler's get(target, prop, receiver) runs whenever a property is read through the proxy.")
JS('a','o',"What does this code print?","console.log(Array(3).fill().map((_, i) => i * 2))","[ 0, 2, 4 ]","[ <3 empty items> ]","[ 2, 4, 6 ]","[ 0, 1, 2 ]","fill() with no argument fills the empty slots with undefined, so map visits every index and doubles it.")
